<script setup>
import {computed,inject,onMounted,reactive,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,errorText} from '../state'
import Icon from '../components/Icon.vue'
import PageTabs from './PageTabs.vue'
import FormGroup from './FormGroup.vue'
import FormRow from './FormRow.vue'
const c=inject('console'),route=useRoute(),router=useRouter(),busy=ref(false),error=ref(''),records=ref([]),rates=ref({}),page=ref(1),total=ref(0),saved=ref('')
const form=reactive({fixed_rates:{USDT:'',USDC:''},interval_seconds:60,history_days:30,api_url:'https://api.coingecko.com',api_key:'',version:0})
const section=computed({get:()=>route.params.section==='settings'?'settings':'history',set:value=>router.replace(`/admin/rates/${value}`)})
const dirty=computed(()=>saved.value&&JSON.stringify(form)!==saved.value)
c.guard(()=>Boolean(dirty.value))
async function load(){try{const [history,config]=await Promise.all([api(`/api/admin/rates?page=${page.value}`),api('/api/admin/rates/settings')]);records.value=history.records;total.value=history.total;rates.value=history.rates;const settings=config.settings;Object.assign(form,{fixed_rates:settings.fixed_rates,interval_seconds:settings.interval_seconds,history_days:settings.history_days,api_url:settings.api_url,api_key:'',version:settings.version});saved.value=JSON.stringify(form)}catch(e){error.value=errorText(e)}}
async function sync(){busy.value=true;error.value='';try{await api('/api/admin/rates/sync',{method:'POST'});await load();c.toast('自动行情已同步')}catch(e){error.value=errorText(e);await load()}finally{busy.value=false}}
async function save(){busy.value=true;error.value='';try{await api('/api/admin/rates/settings',{method:'PUT',body:JSON.stringify(form)});await load();c.toast('汇率设置已保存，仅影响新订单')}catch(e){error.value=errorText(e)}finally{busy.value=false}}
async function changePage(delta){page.value+=delta;await load()}
onMounted(load)
</script>
<template><div class="console-page-heading"><div><h2>汇率监控</h2><p>固定付款报价与自动行情分别维护，订单创建时锁定</p></div><button v-if="section==='history'" class="button button-secondary" :disabled="busy" @click="sync"><Icon :name="busy?'loader':'refresh'" :class="{spin:busy}" :size="16"/>同步行情</button><button v-else class="button" :disabled="busy||!dirty" form="pricing-form">保存汇率设置</button></div><PageTabs v-model="section" :items="[{id:'history',label:'同步记录'},{id:'settings',label:'汇率设置'}]" label="汇率分类"/><p v-if="error" class="error-box" role="alert">{{error}}</p><template v-if="section==='history'"><div class="rates-overview"><article v-for="asset in ['USDT','USDC']" :key="asset" class="hig-card"><div class="rate-symbol">{{asset}} / CNY</div><strong>{{rates[asset]?`${rates[asset].rate} CNY`:'暂无有效行情'}}</strong><p>固定报价：{{form.fixed_rates[asset]?`${form.fixed_rates[asset]} CNY`:'未设置，使用自动行情'}}</p><small v-if="rates[asset]">行情时间 {{new Date(rates[asset].quoted_at*1000).toLocaleString()}}</small></article></div><div class="hig-card table-scroll"><table class="console-table"><thead><tr><th>同步时间</th><th>状态</th><th>结果</th></tr></thead><tbody><tr v-for="row in records" :key="row.id"><td>{{new Date(row.created_at*1000).toLocaleString()}}</td><td><span class="state-badge" :class="row.success?'production':'neutral'">{{row.success?'同步成功':'同步失败'}}</span></td><td>{{row.success?row.message:errorText({message:row.message})}}</td></tr><tr v-if="!records.length"><td colspan="3">尚无同步记录，填写配置后可同步真实行情</td></tr></tbody></table></div><nav v-if="total>20" class="rates-pages"><button class="button button-secondary" :disabled="page===1" @click="changePage(-1)">上一页</button><span>{{page}} / {{Math.ceil(total/20)}}</span><button class="button button-secondary" :disabled="page*20>=total" @click="changePage(1)">下一页</button></nav></template><form v-else id="pricing-form" @submit.prevent="save"><FormGroup title="固定付款报价" note="单位为 1 USDT/USDC = X CNY，固定报价优先；留空使用自动行情"><FormRow v-for="asset in ['USDT','USDC']" :key="asset" :field="`fixed-${asset}`" :label="`${asset} 固定汇率`"><input :id="`fixed-${asset}`" v-model="form.fixed_rates[asset]" type="number" min="0.01" step="0.01" placeholder="留空使用自动报价"/></FormRow></FormGroup><FormGroup title="自动行情同步"><FormRow field="rate-url" label="行情 HTTPS 地址"><input id="rate-url" v-model.trim="form.api_url" type="url" required/></FormRow><FormRow field="rate-key" label="API Key（可选）"><input id="rate-key" v-model="form.api_key" type="password" autocomplete="new-password" placeholder="留空保留已保存密钥"/></FormRow><FormRow field="rate-interval" label="同步周期（秒）" hint="默认 60 秒；市场报价有效期为 180 秒"><input id="rate-interval" v-model.number="form.interval_seconds" type="number" min="30" max="120" required/></FormRow><FormRow field="rate-history" label="记录保留天数"><input id="rate-history" v-model.number="form.history_days" type="number" min="1" max="365" required/></FormRow></FormGroup></form></template>
<style scoped>.rates-overview{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin:18px 0}.rates-overview article{padding:22px}.rate-symbol{font-size:12px;color:var(--muted);margin-bottom:12px}.rates-overview strong{font-size:24px}.rates-overview p{font-size:13px;margin:12px 0 8px}.rates-overview small{font-size:11px;color:var(--muted)}.rates-pages{display:flex;align-items:center;justify-content:flex-end;gap:12px;margin-top:16px}@media(max-width:600px){.rates-overview{grid-template-columns:minmax(0,1fr)}}</style>
